<script setup>
import{ref,reactive,onMounted}from'vue';import{useRoute,useRouter}from'vue-router';import{getWork,getReviews,getFavoriteStatus,toggleFavorite,getLikeStatus,toggleLike,saveReview}from'../api';import{ElMessage}from'element-plus'
const route=useRoute(),router=useRouter(),work=ref(null),reviews=ref([]),favorite=ref(false),liked=ref(false),user=JSON.parse(localStorage.getItem('craft-user')||'null'),review=reactive({rating:5,content:''})
async function load(){work.value=(await getWork(route.params.id)).data;reviews.value=(await getReviews(route.params.id)).data;if(user){try{favorite.value=(await getFavoriteStatus(route.params.id)).data.favorite;liked.value=(await getLikeStatus(route.params.id)).data.liked}catch{}}}
async function fav(){if(!user)return router.push('/login?redirect='+route.fullPath);const d=(await toggleFavorite(route.params.id)).data;favorite.value=d.favorite;ElMessage.success(d.favorite?'已收藏':'已取消收藏')}
async function like(){if(!user)return router.push('/login?redirect='+route.fullPath);const d=(await toggleLike(route.params.id)).data;liked.value=d.liked;work.value.likes=d.likes;ElMessage.success(d.liked?'已点赞':'已取消点赞')}
async function submit(){if(!user)return router.push('/login?redirect='+route.fullPath);await saveReview(route.params.id,review);review.content='';reviews.value=(await getReviews(route.params.id)).data;ElMessage.success('评价已发布')}onMounted(load)
</script>
<template><div v-if="work"><section class="page-hero"><div class="container"><span>{{work.category}}</span><h1>{{work.title}}</h1><p>{{work.summary}}</p></div></section>
<section class="section"><div class="container detail-layout"><img :src="work.image" :alt="work.title" class="detail-img"><div class="panel"><div class="eyebrow">{{work.category}} · CUSTOM CRAFT</div><h2>{{work.title}}</h2><p class="body-copy">{{work.summary}}</p><p>创作者：<b>{{work.creatorName}}</b></p><div class="detail-stats"><span>参考价 <b>¥{{work.price}}</b></span><span>制作周期 <b>{{work.leadDays}} 天</b></span><span>喜欢 <b>{{work.likes}}</b></span></div><div class="detail-buttons"><button class="primary-btn" @click="$router.push('/custom')">以此为灵感发起定制</button><button class="outline-btn" :class="{liked}" @click="like">{{liked?'♥ 已喜欢':'♡ 喜欢'}}</button><button class="outline-btn" @click="fav">{{favorite?'★ 已收藏':'☆ 收藏'}}</button></div></div></div></section>
<section class="section"><div class="container review-layout"><div><h2>作品评价</h2><article v-for="r in reviews" :key="r.id" class="soft-card" style="margin:12px 0"><b>{{r.userName}}</b> · {{r.rating}} 星<p>{{r.content}}</p></article><div v-if="!reviews.length" class="empty-note">还没有评价，登录后可以留下第一条。</div></div><div class="panel"><h3>发布评价</h3><el-rate v-model="review.rating"/><el-input v-model="review.content" type="textarea" :rows="4" maxlength="500" show-word-limit placeholder="说说作品细节、沟通与定制体验"/><button class="primary-btn" style="margin-top:12px" @click="submit">提交评价</button></div></div></section></div></template>